.skeleton-image {
  background: #e5e5e5;
  animation: pulse 1.5s ease-in-out infinite;
}

.skeleton-text {
  height: 1rem;
  background: #e5e5e5;
  border-radius: 4px;
  margin: 0.5rem 1rem;
  animation: pulse 1.5s ease-in-out infinite;
}

.skeleton-text.short {
  width: 60%;
}

.skeleton-text.large {
  height: 2rem;
  width: 70%;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* Let the live page remain interactive below the transition snapshots. */
::view-transition {
  pointer-events: none;
}

::view-transition-group(.product-image-morph) {
  animation-duration: var(--transition-move);
  animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
}

::view-transition-image-pair(.product-image-morph) {
  animation-name: morph-image;
}

::view-transition-old(.nav-forward) {
  --slide-offset: -60px;
  animation:
    var(--transition-exit) ease-in both transition-fade reverse,
    var(--transition-move) ease-in-out both page-slide reverse;
}

::view-transition-new(.nav-forward) {
  --slide-offset: 60px;
  animation:
    var(--transition-enter) ease-out var(--transition-exit) both transition-fade,
    var(--transition-move) ease-in-out both page-slide;
}

::view-transition-old(.nav-back) {
  --slide-offset: 60px;
  animation:
    var(--transition-exit) ease-in both transition-fade reverse,
    var(--transition-move) ease-in-out both page-slide reverse;
}

::view-transition-new(.nav-back) {
  --slide-offset: -60px;
  animation:
    var(--transition-enter) ease-out var(--transition-exit) both transition-fade,
    var(--transition-move) ease-in-out both page-slide;
}

::view-transition-old(.skeleton-exit) {
  animation:
    var(--transition-exit) ease-out both transition-fade reverse,
    var(--transition-exit) ease-out both content-rise reverse;
}

::view-transition-new(.content-enter) {
  animation:
    var(--transition-enter) ease-out var(--transition-exit) both transition-fade,
    var(--transition-move) ease-out both content-rise;
}

@keyframes transition-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes page-slide {
  from {
    translate: var(--slide-offset) 0;
  }
  to {
    translate: 0 0;
  }
}

@keyframes content-rise {
  from {
    transform: translateY(10px);
  }
  to {
    transform: translateY(0);
  }
}

@keyframes morph-image {
  35% {
    filter: blur(2px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .skeleton-image,
  .skeleton-text {
    animation: none;
  }

  ::view-transition-old(*),
  ::view-transition-new(*),
  ::view-transition-group(*) {
    animation-duration: 0.001ms !important;
    animation-delay: 0s !important;
  }
}

